/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Load clean modern Inter font at the module level
const { fontFamily: interFamily } = loadInter();



export type InfographicChartProps = Record<string, any>;

const InfographicChart: React.FC<InfographicChartProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 8,
  totalMale = 23.5,
  elementaryMale = 13.0,
  secondaryMale = 36.0,
  maleColor = "#002f87",
  femaleColor = "#792fe0",
  barHeightRatio = 0.10,
  labelFontSizePercent = 2.4,
  axisFontSizePercent = 1.6,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Prevent background parser issues
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive dimensions based on baseline video configuration
  const chartX = width * 0.22;
  const chartWidth = width * 0.70;
  const chartY = height * 0.12;
  const chartHeight = height * 0.65;
  const barHeight = height * barHeightRatio;
  const labelFontSize = height * (labelFontSizePercent / 100);
  const axisFontSize = height * (axisFontSizePercent / 100);

  // Animation Timing Logic (sequential animation)
  const durationInFrames = durationInSeconds * fps;
  const startOffset = Math.floor(0.06 * durationInFrames); // Small start pause for structure
  const endOffset = Math.floor(0.12 * durationInFrames);   // End pause to admire finished graphic
  const totalAnimFrames = Math.max(1, durationInFrames - startOffset - endOffset);
  const rowAnimFrames = Math.max(1, totalAnimFrames / 3);

  // Setup rows config
  const rowData = [
    { label: "TOTAL", malePercent: totalMale },
    { label: "ELEMENTARY", malePercent: elementaryMale },
    { label: "SECONDARY", malePercent: secondaryMale },
  ];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, overflow: "hidden" }}>
      {/* 1. Grid Lines (Dashed Vertical Lines) */}
      {Array.from({ length: 11 }).map((_, i) => {
        const lineX = chartX + (i / 10) * chartWidth;
        return (
          <div
            key={`grid-${i}`}
            style={{
              position: "absolute",
              left: lineX,
              top: chartY,
              width: 1,
              height: chartHeight,
              borderLeft: "2px dashed #cccccc",
              opacity: 0.6,
              transition: "none",
            }}
          />
        );
      })}

      {/* 2. Horizontal Axis Line */}
      <div
        style={{
          position: "absolute",
          left: chartX,
          top: chartY + chartHeight,
          width: chartWidth,
          height: 2,
          backgroundColor: "#444444",
          transition: "none",
        }}
      />

      {/* 3. Ticks and Labels along the Horizontal Axis */}
      {Array.from({ length: 11 }).map((_, i) => {
        const x = chartX + (i / 10) * chartWidth;
        return (
          <div
            key={`tick-${i}`}
            style={{
              position: "absolute",
              left: x,
              top: chartY + chartHeight,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              transform: "translateX(-50%)",
              transition: "none",
            }}
          >
            {/* Tick Mark */}
            <div
              style={{
                width: 2,
                height: 8,
                backgroundColor: "#444444",
                transition: "none",
              }}
            />
            {/* Number Label */}
            <div
              style={{
                marginTop: 8,
                fontSize: axisFontSize,
                fontWeight: "600",
                color: "#1e293b",
                fontFamily: interFamily,
                transition: "none",
              }}
            >
              {i * 10}
            </div>
          </div>
        );
      })}

      {/* 4. Row Labels and Animated Bars */}
      {rowData.map((row, i) => {
        const rowHeight = chartHeight / 3;
        const barY = chartY + i * rowHeight + (rowHeight - barHeight) / 2;

        // Custom timing calculations per row
        const rowStart = startOffset + i * rowAnimFrames;
        const rowEnd = rowStart + rowAnimFrames;
        const maleDuration = rowAnimFrames * 0.40; // 40% of row duration for male
        const rowMaleEnd = rowStart + maleDuration;

        // Animate Male segment width percentage
        const maleWidthPercentCurrent = interpolate(
          frame,
          [rowStart, rowMaleEnd],
          [0, row.malePercent],
          {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.bezier(0.25, 1, 0.5, 1),
          }
        );

        // Animate Female segment width percentage starting from Male segment's completion
        const femaleWidthPercentCurrent = interpolate(
          frame,
          [rowMaleEnd, rowEnd],
          [0, 100 - row.malePercent],
          {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.bezier(0.25, 1, 0.5, 1),
          }
        );

        const currentMaleWidth = chartWidth * (maleWidthPercentCurrent / 100);
        const currentFemaleWidth = chartWidth * (femaleWidthPercentCurrent / 100);
        const femaleLeft = chartX + chartWidth * (row.malePercent / 100);

        return (
          <React.Fragment key={`row-${row.label}`}>
            {/* Row Label (completely static) */}
            <div
              style={{
                position: "absolute",
                left: width * 0.02,
                width: chartX - width * 0.05,
                top: barY,
                height: barHeight,
                display: "flex",
                alignItems: "center",
                justifyContent: "flex-end",
                fontSize: labelFontSize,
                fontWeight: "800",
                color: "#111111",
                textAlign: "right",
                letterSpacing: "-0.03em",
                fontFamily: interFamily,
                transition: "none",
              }}
            >
              {row.label}
            </div>

            {/* Male segment bar */}
            <div
              style={{
                position: "absolute",
                left: chartX,
                top: barY,
                width: currentMaleWidth,
                height: barHeight,
                backgroundColor: maleColor,
                transition: "none",
              }}
            />

            {/* Female segment bar */}
            <div
              style={{
                position: "absolute",
                left: femaleLeft,
                top: barY,
                width: currentFemaleWidth,
                height: barHeight,
                backgroundColor: femaleColor,
                transition: "none",
              }}
            />
          </React.Fragment>
        );
      })}

      {/* 5. Bottom Center Legend (completely static) */}
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          bottom: height * 0.05,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          gap: 60,
          fontFamily: interFamily,
          transition: "none",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 16, transition: "none" }}>
          <div
            style={{
              width: Math.min(width, height) * 0.045,
              height: Math.min(width, height) * 0.045,
              backgroundColor: maleColor,
              borderRadius: 3,
              transition: "none",
            }}
          />
          <span
            style={{
              fontSize: axisFontSize * 1.15,
              fontWeight: "800",
              color: "#111111",
              letterSpacing: "-0.02em",
              transition: "none",
            }}
          >
            MALE
          </span>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 16, transition: "none" }}>
          <div
            style={{
              width: Math.min(width, height) * 0.045,
              height: Math.min(width, height) * 0.045,
              backgroundColor: femaleColor,
              borderRadius: 3,
              transition: "none",
            }}
          />
          <span
            style={{
              fontSize: axisFontSize * 1.15,
              fontWeight: "800",
              color: "#111111",
              letterSpacing: "-0.02em",
              transition: "none",
            }}
          >
            FEMALE
          </span>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default InfographicChart;